use vstd::prelude::*;

verus! {
    /// Copies the input vector `t` into a new vector `out`.
    ///
    /// Ensures that `out` has the same length as `t` and that
    /// every element of `out` matches the corresponding element of `t`.
    fn solve(t: Vec<char>) -> (out: Vec<char>)
        ensures
            out.len() == t.len(),
            forall |i: usize| i < t.len() ==> out[i] == t[i],
    {
        let n = t.len();
        let mut out = Vec::with_capacity(n);
        let mut i = 0;

        while i < n
            invariant
                // `i` never exceeds the input length
                i <= n,
                // `out.len()` advances in lock-step with `i`
                out.len() == i,
                // For all positions already copied, `out[j] == t[j]`
                forall |j: usize| j < i ==> out[j] == t[j],
            decreases n - i,
        {
            out.push(t[i]);
            i += 1;
        }

        out
    }
}

